def calcular_precio_unitario(apps, schema_editor):
    DetalleVenta = apps.get_model('core', 'DetalleVenta')
    for detalle in DetalleVenta.objects.all():
        if detalle.cantidad:
            detalle.precio_unitario = (detalle.subtotal / detalle.cantidad).quantize(
                Decimal('0.01'), rounding=ROUND_HALF_UP
            )
            detalle.save(update_fields=['precio_unitario'])


